1	import { Schema } from "effect";
2	import { ActionId, type ActionStatus } from "../actions/Action.ts";
3	import { TeamId } from "../people/Team.ts";
4	import { Dimension } from "../pulses/Question.ts";
5	import { RoundId } from "./Round.ts";
6	import { enforceEffectiveNOnResult, type RoundResult } from "./Results.ts";
7	
8	/** One shared Round on the overview's time axis. */
9	export const OverviewRound = Schema.Struct({ roundId: RoundId, plannedOpenDate: Schema.String });
10	export type OverviewRound = typeof OverviewRound.Type;
11	
12	/** A Dimension's score in one shared Round; null is a gap (below the effective minimum group size, or not asked). */
13	export const OverviewPoint = Schema.Struct({ roundId: RoundId, score: Schema.NullOr(Schema.Finite) });
14	export type OverviewPoint = typeof OverviewPoint.Type;
15	
16	/** One Dimension's line across all shared Rounds, one point per Round in the same order. */
17	export const DimensionOverview = Schema.Struct({ dimension: Dimension, points: Schema.Array(OverviewPoint) });
18	export type DimensionOverview = typeof DimensionOverview.Type;
19	
20	/** An Action committed or done, at that moment (epoch ms). */
21	export const ActionMarker = Schema.Struct({
22	  actionId: ActionId,
23	  title: Schema.String,
24	  kind: Schema.Literals(["committed", "done"]),
25	  at: Schema.Int,
26	});
27	export type ActionMarker = typeof ActionMarker.Type;
28	
29	/** The Team health overview: one line per Dimension across all shared Rounds, plus Action markers. */
30	export const TeamOverview = Schema.Struct({
31	  teamId: TeamId,
32	  rounds: Schema.Array(OverviewRound),
33	  dimensions: Schema.Array(DimensionOverview),
34	  markers: Schema.Array(ActionMarker),
35	});
36	export type TeamOverview = typeof TeamOverview.Type;
37	
38	/** The Action fields the overview reads. Actions have no minimum group size. */
39	export interface OverviewActionInput {
40	  readonly id: ActionId;
41	  readonly title: string;
42	  readonly status: ActionStatus;
43	  readonly createdAt: number;
44	  readonly doneAt: number | null;
45	}
46	
47	const compareStrings = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
48	
49	/** The point for one Dimension in one Round: a score only when the Round and the Dimension both meet N. */
50	const pointScore = (result: RoundResult, dimension: Dimension): number | null => {
51	  if (!result.meetsMinimumGroupSize) return null;
52	  const dimensionResult = result.dimensions.find((each) => each.dimension === dimension);
53	  if (dimensionResult === undefined || !dimensionResult.meetsMinimumGroupSize) return null;
54	  return dimensionResult.score;
55	};
56	
57	/**
58	 * Builds the Team health overview from the stored Results of the Team's Rounds and its Actions.
59	 * Only shared Rounds appear. Each Result is enforced against the current minimum group size first
60	 * (ADR 0004), so a Round below its effective N, or one that was raised past, is a gap.
61	 */
62	export const buildTeamOverview = (params: {
63	  readonly teamId: TeamId;
64	  readonly results: ReadonlyArray<RoundResult>;
65	  readonly minimumGroupSize: number;
66	  readonly actions: ReadonlyArray<OverviewActionInput>;
67	}): TeamOverview => {
68	  const shared = params.results
69	    .filter((result) => result.status === "shared")
70	    .map((result) => enforceEffectiveNOnResult(result, params.minimumGroupSize))
71	    .sort(
72	      (a, b) => compareStrings(a.plannedOpenDate, b.plannedOpenDate) || compareStrings(a.roundId, b.roundId),
73	    );
74	
75	  const dimensions: Array<DimensionOverview> = [];
76	  for (const dimension of Dimension.literals) {
77	    // A Result lists every Dimension, so "asked" is read from its Rating Questions: only those score a Dimension.
78	    const asked = shared.some((result) =>
79	      result.questions.some(
80	        (question) => question.dimension === dimension && question.type._tag === "Rating",
81	      ),
82	    );
83	    if (!asked) continue;
84	    dimensions.push({
85	      dimension,
86	      points: shared.map((result) => ({ roundId: result.roundId, score: pointScore(result, dimension) })),
87	    });
88	  }
89	
90	  const markers: Array<ActionMarker> = [];
91	  for (const action of params.actions) {
92	    if (action.status !== "committed" && action.status !== "done") continue;
93	    markers.push({ actionId: action.id, title: action.title, kind: "committed", at: action.createdAt });
94	    if (action.status === "done" && action.doneAt !== null) {
95	      markers.push({ actionId: action.id, title: action.title, kind: "done", at: action.doneAt });
96	    }
97	  }
98	  markers.sort(
99	    (a, b) =>
100	      a.at - b.at ||
101	      Number(a.kind === "done") - Number(b.kind === "done") ||
102	      compareStrings(a.actionId, b.actionId),
103	  );
104	
105	  return {
106	    teamId: params.teamId,
107	    rounds: shared.map((result) => ({ roundId: result.roundId, plannedOpenDate: result.plannedOpenDate })),
108	    dimensions,
109	    markers,
110	  };
111	};
