63	/** Hand-built SVG 12-round trend line chart. `unusual` marks the latest point in brass. */
64	export const trendChart = <Message>(
65	  points: ReadonlyArray<TrendPoint | DimensionTrendPoint>,
66	  h: HtmlBuilder<Message>,
67	  unusual = false,
68	): Html => {
69	  if (points.length === 0) return null;
70	
71	  const width = 360;
72	  const height = 120;
73	  const padLeft = 24;
74	  const padRight = 16;
75	  const padTop = 16;
76	  const padBottom = 24;
77	
78	  const chartW = width - padLeft - padRight;
79	  const chartH = height - padTop - padBottom;
80	
81	  const minScore = 1.0;
82	  const maxScore = 5.0;
83	
84	  const getX = (idx: number) => {
85	    if (points.length <= 1) return padLeft + chartW / 2;
86	    return padLeft + (idx / (points.length - 1)) * chartW;
87	  };
88	
89	  const getY = (score: number) => {
90	    const norm = (score - minScore) / (maxScore - minScore);
91	    return padTop + (1 - norm) * chartH;
92	  };
93	
94	  const svgChildren = [];
95	
96	  // Horizontal guide lines at 1.0, 3.0, 5.0
97	  for (const s of [1, 3, 5]) {
98	    const y = getY(s);
99	    svgChildren.push(
100	      h.line([
101	        h.X1(String(padLeft)),
102	        h.Y1(String(y)),
103	        h.X2(String(width - padRight)),
104	        h.Y2(String(y)),
105	        h.Class("stroke-line"),
106	      ]),
107	    );
108	  }
109	
110	  // Draw lines between consecutive non-gap points
111	  for (let i = 0; i < points.length - 1; i++) {
112	    const p1 = points[i]!;
113	    const p2 = points[i + 1]!;
114	    if (p1.score !== null && p2.score !== null && !p2.hasGap) {
115	      svgChildren.push(
116	        h.line([
117	          h.X1(String(getX(i))),
118	          h.Y1(String(getY(p1.score))),
119	          h.X2(String(getX(i + 1))),
120	          h.Y2(String(getY(p2.score))),
121	          h.Class("stroke-primary"),
122	          h.StrokeWidth("2"),
123	        ]),
124	      );
125	    }
126	  }
127	
128	  // Draw dot markers
129	  for (let i = 0; i < points.length; i++) {
130	    const p = points[i]!;
131	    if (p.score !== null) {
132	      svgChildren.push(
133	        h.circle([
134	          h.Cx(String(getX(i))),
135	          h.Cy(String(getY(p.score))),
136	          h.R("4"),
137	          h.Class(unusual && i === points.length - 1 ? "fill-brass" : "fill-primary"),
138	        ]),
139	      );
140	    }
141	  }
142	
143	  return h.svg(
144	    [
145	      h.ViewBox(`0 0 ${width} ${height}`),
146	      h.Class("h-32 w-full max-w-sm overflow-hidden"),
147	      h.Role("img"),
148	      h.AriaLabel(message("results.trend12Rounds")),
149	    ],
150	    svgChildren,
151	  );
152	};
