172	/** Hand-built SVG distribution bar chart. */
173	export const distributionChart = <Message>(
174	  distribution: ReadonlyArray<DistributionOption>,
175	  h: HtmlBuilder<Message>,
176	): Html => {
177	  if (distribution.length === 0) return null;
178	  const maxCount = Math.max(...distribution.map((d) => d.count), 1);
179	  const width = 300;
180	  const barHeight = 20;
181	  const gap = 8;
182	  const height = distribution.length * (barHeight + gap);
183	
184	  const rects = distribution.map((d, idx) => {
185	    const y = idx * (barHeight + gap);
186	    const barW = Math.max((d.count / maxCount) * (width - 60), 2);
187	    return h.g(
188	      [],
189	      [
190	        h.rect([
191	          h.X("40"),
192	          h.Y(String(y)),
193	          h.Width(String(barW)),
194	          h.Height(String(barHeight)),
195	          h.Rx("4"),
196	          h.Class("fill-primary"),
197	        ]),
198	        h.text([h.X("10"), h.Y(String(y + barHeight - 4)), h.Class("fill-ink text-xs")], [String(d.option)]),
199	        h.text(
200	          [h.X(String(45 + barW)), h.Y(String(y + barHeight - 4)), h.Class("fill-muted text-xs")],
201	          [String(d.count)],
202	        ),
203	      ],
204	    );
205	  });
206	
207	  return h.svg(
208	    [
209	      h.ViewBox(`0 0 ${width} ${height}`),
210	      h.Class("w-full max-w-xs overflow-hidden"),
211	      h.Role("img"),
212	      h.AriaLabel(message("results.distributionTitle")),
213	    ],
214	    rects,
215	  );
216	};
