414	export const resultsScreenView = <Message>(
415	  state: {
416	    readonly results: LoadedResults;
417	    readonly actions: LoadedActions;
418	    readonly teamDetail: LoadedTeam;
419	    readonly showTable: Record<string, boolean>;
420	    readonly actionTitle: string;
421	    readonly actionOwnerId: Option.Option<PersonId>;
422	    readonly actionDueDate: string;
423	    readonly actionDimension: Dimension | "none";
424	    readonly actionBusy: boolean;
425	    readonly actionFailure: Option.Option<Failure>;
426	  },
427	  callbacks: {
428	    readonly onToggleTable: (key: string) => Message;
429	    readonly onActionTitleChange: (title: string) => Message;
430	    readonly onActionOwnerChange: (personId: string) => Message;
431	    readonly onActionDueDateChange: (date: string) => Message;
432	    readonly onActionDimensionChange: (dim: string) => Message;
433	    readonly onSubmitAction: Message;
434	    readonly onUpdateActionStatus: (actionId: ActionId, status: ActionStatus) => Message;
435	  },
436	  h: HtmlBuilder<Message>,
437	): Html => {
438	  if (state.results._tag === "Loading") {
439	    return h.p([h.Class("text-muted")], [message("app.loading")]);
440	  }
441	
442	  if (state.results._tag === "Failed") {
443	    return alertView(failureMessage(state.results.failure), h);
444	  }
445	
446	  const result = state.results.result;
447	  const minimum = result.effectiveMinimumGroupSize;
448	
449	  const children: Array<Html> = [
450	    h.a([h.Href(teamHref(result.teamId)), h.Class(linkClass)], [message("results.back")]),
451	    h.div([h.Class("mt-4")], [pageTitle(message("results.title"), h)]),
452	    h.p([h.Class("text-muted")], [message("results.roundDate", { date: result.plannedOpenDate })]),
453	  ];
454	  const summary = resultsSummary(result);
455	  if (summary !== null) {
456	    children.push(
457	      h.p(
458	        [h.Class("mt-6 font-display text-[26px] leading-[1.25] tracking-tight text-ink sm:text-[32px]")],
459	        [summary],
460	      ),
461	    );
462	  }
463	
464	  if (result.delayed) {
465	    children.push(
466	      h.div(
467	        [h.Role("alert"), h.Class("rounded-control border border-line bg-surface p-4")],
468	        [
469	          h.h2([h.Class("font-semibold")], [message("results.delayedTitle")]),
470	          h.p([h.Class("mt-1 text-sm text-muted")], [message("results.delayedBody")]),
471	        ],
472	      ),
473	    );
474	  }
475	
476	  // Actions section: shown for all closed rounds (ADR 0004: Actions list has no minimum group size)
477	  const isLead = state.teamDetail._tag === "Loaded" && state.teamDetail.detail.team.yourRole === "lead";
478	  const roster = state.teamDetail._tag === "Loaded" ? state.teamDetail.detail.roster : [];
479	
480	  const actionsItems: Array<Html> = [];
481	
482	  if (state.actions._tag === "Loading") {
483	    actionsItems.push(h.p([h.Class("text-sm text-mint-text")], [message("app.loading")]));
484	  } else if (state.actions._tag === "Failed") {
485	    actionsItems.push(alertView(failureMessage(state.actions.failure), h));
486	  } else {
487	    const list = state.actions.actions;
488	    if (list.length === 0) {
489	      actionsItems.push(h.p([h.Class("text-sm text-mint-text italic")], [message("actions.empty")]));
