1	import { catalog } from "./catalog.ts";
2	
3	type Catalog = typeof catalog;
4	export type MessageKey = keyof Catalog;
5	type Value = string | number;
6	
7	type Placeholders<T extends string> = T extends `${string}{${infer Name}}${infer Rest}`
8	  ? Name | Placeholders<Rest>
9	  : never;
10	type Params<K extends MessageKey> = Readonly<Record<Placeholders<Catalog[K]>, Value>>;
11	type KeysWithoutParams = {
12	  [K in MessageKey]: [Placeholders<Catalog[K]>] extends [never] ? K : never;
13	}[MessageKey];
14	type KeysWithParams = Exclude<MessageKey, KeysWithoutParams>;
15	
16	type PluralBase<K extends string> = K extends `${infer Base}.other` ? Base : never;
17	export type PluralKey = PluralBase<MessageKey>;
18	type PluralParams<B extends PluralKey> = Readonly<
19	  Record<Exclude<Placeholders<Catalog[`${B}.other`]>, "count">, Value>
20	>;
21	
22	const LOCALE = "en";
23	let cachedPluralRules: Intl.PluralRules | undefined;
24	function getPluralRules(): Intl.PluralRules {
25	  if (!cachedPluralRules) {
26	    cachedPluralRules = new Intl.PluralRules(LOCALE);
27	  }
28	  return cachedPluralRules;
29	}
30	
31	const isMessageKey = (key: string): key is MessageKey => Object.hasOwn(catalog, key);
32	
33	function fill(template: string, params: Readonly<Record<string, Value>>): string {
34	  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(params[name] ?? ""));
35	}
36	
37	/** Looks up a message; placeholders are checked against the template at compile time. */
38	export function message<K extends KeysWithoutParams>(key: K): string;
39	export function message<K extends KeysWithParams>(key: K, params: Params<K>): string;
40	export function message(key: MessageKey, params: Readonly<Record<string, Value>> = {}): string {
41	  return fill(catalog[key], params);
42	}
43	
44	/** Picks the plural form for `count` with `Intl.PluralRules`; `{count}` is filled in. */
45	export function pluralMessage<B extends PluralKey>(base: B, count: number, params?: PluralParams<B>): string {
46	  const specific = `${base}.${getPluralRules().select(count)}`;
47	  const template = isMessageKey(specific) ? catalog[specific] : catalog[`${base}.other`];
48	  return fill(template, { ...params, count: new Intl.NumberFormat(LOCALE).format(count) });
49	}
50	
51	/** Formats a date for display with `Intl.DateTimeFormat`. */
52	export function formatDate(
53	  date: Date,
54	  options: Intl.DateTimeFormatOptions = { dateStyle: "medium" },
55	): string {
56	  return new Intl.DateTimeFormat(LOCALE, options).format(date);
57	}
