110	/** Table view: one row per shared Round, one column per Dimension; a gap reads as "Too few answers". */
111	const roundsTable = <Message>(overview: TeamOverview, h: HtmlBuilder<Message>): Html => {
112	  const scoresByDimension = overview.dimensions.map(
113	    (dimension) =>
114	      new Map<string, number | null>(
115	        dimension.points.map((point): readonly [string, number | null] => [point.roundId, point.score]),
116	      ),
117	  );
118	  return dataTable(
119	    [message("overview.tableRoundDate"), ...overview.dimensions.map((d) => dimensionName(d.dimension))],
120	    overview.rounds.map((round) => [
121	      round.plannedOpenDate,
122	      ...scoresByDimension.map((scores) => {
123	        const score = scores.get(round.roundId) ?? null;
124	        return score !== null ? String(score) : message("overview.gap");
125	      }),
126	    ]),
127	    h,
128	  );
129	};
130	
131	const markersTable = <Message>(markers: ReadonlyArray<ActionMarker>, h: HtmlBuilder<Message>): Html =>
132	  dataTable(
133	    [message("overview.tableDate"), message("overview.tableAction"), message("overview.tableEvent")],
134	    markers.map((marker) => [
135	      formatDate(new Date(marker.at)),
136	      marker.title,
137	      message(marker.kind === "committed" ? "overview.event.committed" : "overview.event.done"),
138	    ]),
139	    h,
140	  );
141	
142	/** The Team health overview on the Team page: Dimension trend lines with Action markers, or tables. */
143	export const teamOverviewView = <Message>(
144	  state: LoadedOverview,
145	  isTable: boolean,
146	  onToggleTable: Message,
147	  h: HtmlBuilder<Message>,
148	): Html => {
149	  if (state._tag === "Loading") {
150	    return h.p([h.Class("text-muted")], [message("overview.loading")]);
151	  }
152	
153	  if (state._tag === "Failed") {
154	    // Organization admins outside the Team are refused; the page then simply shows no overview.
155	    if (state.failure === "Forbidden") return null;
156	    return problemView(state.failure, h);
157	  }
158	
159	  const { overview } = state;
160	  if (overview.rounds.length === 0) {
161	    return h.section(
162	      [h.Class("flex flex-col gap-4")],
163	      [sectionTitle(message("overview.title"), h), emptyState(message("overview.empty"), h)],
164	    );
165	  }
166	
167	  // One shared time axis: planned open dates and Action times. Clamped so no point leaves the plot.
168	  let tMin = Number.POSITIVE_INFINITY;
169	  let tMax = Number.NEGATIVE_INFINITY;
170	  for (const round of overview.rounds) {
171	    tMin = Math.min(tMin, Date.parse(round.plannedOpenDate));
172	    tMax = Math.max(tMax, Date.parse(round.plannedOpenDate));
173	  }
174	  for (const marker of overview.markers) {
175	    tMin = Math.min(tMin, marker.at);
176	    tMax = Math.max(tMax, marker.at);
177	  }
178	  const xOf = (t: number): number => {
179	    if (tMax === tMin) return 0.5;
180	    return Math.min(1, Math.max(0, (t - tMin) / (tMax - tMin)));
181	  };
182	
183	  const xByRound = new Map<string, number>();
184	  for (const round of overview.rounds) {
185	    xByRound.set(round.roundId, xOf(Date.parse(round.plannedOpenDate)));
186	  }
187	  const markerXs = overview.markers.map((marker) => xOf(marker.at));
188	
189	  const children: Array<Html> = [
190	    sectionTitle(message("overview.title"), h),
191	    h.p([h.Class("text-muted")], [message("overview.intro")]),
192	    h.div([h.Class("flex justify-end")], [toggleButton(isTable, onToggleTable, h)]),
193	  ];
194	
195	  if (isTable) {
196	    children.push(plotBox([roundsTable(overview, h)], h));
197	    if (overview.markers.length > 0) {
198	      children.push(plotBox([markersTable(overview.markers, h)], h));
199	    }
200	  } else {
201	    if (overview.markers.length > 0) {
202	      children.push(
203	        panel(
204	          [
205	            plotBox(
206	              [
207	                h.div(
208	                  [
209	                    h.Role("group"),
210	                    h.AriaLabel(message("overview.markersLabel")),
211	                    h.Class("relative h-8 w-full"),
212	                  ],
213	                  overview.markers.map((marker, i) => markerButton(marker, markerXs[i] ?? 0.5, h)),
214	                ),
215	                legend(h),
216	              ],
217	              h,
218	            ),
219	          ],
220	          h,
221	          "flex flex-col gap-2",
222	        ),
223	      );
224	    }
225	    for (const dimension of overview.dimensions) {
226	      children.push(dimensionPanel(dimension, xByRound, markerXs, h));
227	    }
228	  }
229	
230	  return h.section([h.Class("flex flex-col gap-4")], children);
231	};
